#include <stdio.h>

int main(void) {
    int bowls[3];

    for (int i = 0; i < 3; i++) {
        bowls[i] = {base} + i * {step};
    }

    for (int i = 0; i < 3; i++) {
        printf("第 %d 只：%d\n", i, *(bowls + i));
    }
    return 0;
}
